from pathlib import Path
import json,html,hashlib
R=Path(__file__).resolve().parent;P=R.parent
def read(n):return json.loads((R/n).read_text())
def save(n,x):(R/n).write_text(json.dumps(x,indent=2,ensure_ascii=False),encoding='utf-8')
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
e=lambda v:html.escape(str(v))
c=read('COUNTS.json');ev=read('EVENTS.json');a=read('ALTERNATES.json');s=read('SUMMARY.json')
hc=[x for x in c if x['reading']=='H'];hs=next(x for x in s if x['reading']=='H');astro=next(x for x in hc if x['section']=='Astronomy/Astrology')
sources=[dict(title='Gower, Confessio Amantis VII.1310–1327',date='Work c.1390; electronic edition based on Macaulay',url='https://www.gutenberg.org/files/266/266-h/266-h.htm',status='Primary text in later electronic edition, not manuscript collation',finding='Pliades / Clota with Cristall and Fenele; Aldeboran with Carbunculum and Anabulla. Verifies medieval fennel correspondence, not modern species identity of Anabulla.'),dict(title='Macaulay, introduction to Gower',date='Later critical edition; work date 1390',url='https://www.gutenberg.org/cache/epub/71162/pg71162-images.html',status='Editorial chronology',finding='Dates first completion to 1390 using prologue date.'),dict(title='Tadhg Ó Cuinn, An Irish Materia Medica, subsection 28',date='Historical medical text in modern edited/translated presentation; manuscript dating not audited here',url='https://celt.ucc.ie/published/G600005/text642.html',status='Primary medical text in translation',finding='Links Anabulla, titimaillus and spurge. Supports a spurge reading tradition; does not establish a universal modern taxon.'),dict(title='Agrippa, Occult Philosophy I.32',date='Renaissance work; 1651 English translation in electronic edition',url='https://esotericarchives.com/agrippa/op1.htm',status='Later primary witness; English translation wording',finding='Pleiades with fennel among other materials; Aldeboran with Milky Thistle and Matry-silva. English phrase is not proof of medieval Silybum marianum assignment. Latin scan search snippet was encountered but full scan fetch failed; Latin wording not independently verified in this audit.')]
save('SOURCES.json',sources)
register=dict(status='Forward exploratory candidate register; old frozen experiments unchanged.',oalch=dict(full_forms=['oalcheol','oalcheg','oalchdm'],views={'unstripped':['oalcheol','oalcheg','oalchdm'],'candidate_o':['alcheol','alcheg','alchdm'],'candidate_oa':['lcheol','lcheg','lchdm'],'candidate_oal':['cheol','cheg','chdm']},alternates='f68v2 F/U allchdm stays separate; g/m/y endings are not merged.',qualification='Functional prefixes unproved; no core selected; three H hits selected after observing astronomy anchor.'),doar_daro='Separate literal strings. No metathesis rule, phonetic equivalence or common family established.',modern_sources='Admit dated hypothesis records with author, exact rule, first attestation verified, taxonomic uncertainty and discovery provenance. A modern match prompts a historical search; it cannot by itself establish an older root.',next_test='Before scoring a botanical link, select illustrated plant candidates from independently documented image criteria/sources without using these words. Retain non-fennel alternatives and control pages. Freeze plant list, word variants, transcription policies and comparisons before scoring. This audit establishes no fennel drawing or star identification.')
save('CANDIDATE-REGISTER.json',register)
save('EXECUTION-NOTES.json',dict(section_schema='Actual atlas uses one combined Astronomy/Astrology category. The pre-search protocol anticipated possible separate Astronomy and Astrology values; none exist. Execution preserves the existing combined category, with no post hoc split.',coverage='18 reading codes are alternate partial records and editorial traditions, not 18 complete independent transcriptions. F has only329 readable Astronomy/Astrology tokens and no g tokens in the entire atlas; F absence is not a negative glyph finding.',botanical_schema='Atlas Botanical is a section label, not a guarantee of a plant drawing: f57v is a diagram. Its daro and otodarod hits are separately flagged and excluded from claims about illustrated herbal pages.',no_new_plant_identification=True,html_visual_review=False))
save('FINDINGS.json',dict(H_readable_tokens=hs['tokens'],H_astro_tokens=astro['tokens'],H_astro_share=astro['tokens']/hs['tokens'],H_alch_substring=87,H_alch_initial=22,H_alch_whole=0,H_oalch_initial=3,H_final_g_total=79,H_astro_final_g=17,H_final_g_share_fold=(17/79)/(astro['tokens']/hs['tokens']),H_final_g_rate_ratio=(17/astro['tokens'])/(62/(hs['tokens']-astro['tokens'])),H_illustrated_herbal_daro_initial_loci=['f14v.P.4','f18r.P.1','f18v.P.8','f19v.P.2'],extra_alternate_loci=['f24v.P.14 C doar vs H/F/U doiir','f43v.P.15 C/F/G/U darody vs H darod*'],clothing='New image audit v88 reports five of14 eligible groups mixed. Same-agent annotation, no table alignment scoring. Earlier v87 zero variance pertains to old stored labels.',historical='Gower confirms Pleiades-fennel; Aldebaran-Anabulla must not be silently replaced by modern milk thistle.',semantics_established=False))
body='<h1>oalch · a lead, with its alternatives intact</h1><p>Descriptive replication of Claude’s claims across every available atlas reading code. No sound fitting, prefix assignment, star identification or plant identification.</p>'
body+='<h2>What reproduces</h2><p>H has three initial oalch- tokens, all in the combined Astronomy/Astrology section. H/U/V agree on oalcheol at the curved connector, and H/K/U/V agree on the Aries label oalcheg. The paragraph word oalchdm is H-only: F/U read allchdm. These are three physical locations, not independent evidence multiplied by transcription count.</p>'
for l in ['f68r3.X.2','f68v2.P.5','f70v1.S2.6']:
 body+='<p><b>'+e(l)+'</b>: '+e(' | '.join(x['reading']+': '+x['raw'] for x in a[l]))+'</p>'
body+='<p>The connector oalcheol is not the compact cluster’s own label: that is H/U doaro, V doary. The connector, a figure label and paragraph text do not yet establish a shared referent. All three H oalch hits are hand4, so hand and section are confounded. Neither the concentration nor dropping o establishes its function.</p>'
body+='<h2>The 87 is a substring count</h2><p>H has87 tokens containing alch anywhere,22 starting with alch, and zero exact alch words. The87 includes the three oalch words. They span several sections, but “evenly distributed” is too strong: astronomy/astrology contains14/87 (16.1%) against8.05% of H tokens, and Recipes has0/87 against6.69% of H tokens. These exposed descriptive comparisons receive no confirmatory p-value.</p>'
body+='<table><tr><th>H section</th><th>Readable tokens</th><th>Token share</th><th>Contains alch</th><th>Starts alch</th><th>Starts oalch</th><th>Ends g</th></tr>'
for x in hc:body+='<tr>'+''.join('<td>'+e(v)+'</td>' for v in [x['section'],x['tokens'],f"{100*x['tokens']/hs['tokens']:.2f}%",x['alch_substring'],x['alch_initial'],x['oalch_initial'],x['final_g']])+'</tr>'
body+='</table><h2>Rare final g: concentration with a transcription warning</h2><p>H has79 final-g tokens,17 in astronomy/astrology:21.5% against8.05% of tokens, a2.67-fold share ratio. Comparing within-section token rates gives3.13-fold (a different denominator). This broadly reproduces Claude’s approximate2.5 claim but does not identify a category. Hand, format and terminal position remain uncontrolled. The prior image audit found plausible graphic/encoding effects and36 F m endings in38 strictly aligned H-g/F comparisons; no global g=m rule was established. F has no g tokens at all here, so pooled-transcription g statistics would be misleading.</p><p><a href="../g-ending-audit-v89/report.html">Ending image audit and retained disagreements</a></p>'
body+='<h2>The broader herbal query is not empty</h2><p>No available reading has an oalch substring on an atlas Botanical row. H has no Botanical doar substring, but H does have darody f14v, darodsf f18r, daror f18v and darom f19v in paragraph text. Other readings add darody f43v (H darod*), and C has doar f24v where H/F/U read doiir. Exact doaro is absent from Botanical rows. These string matches are not an established doaro family, and none identifies fennel. Atlas Botanical also includes the non-herbal diagram f57v: its daro and otodarod hits must not be presented as plant-page links.</p>'
for l in ['f14v.P.4','f18r.P.1','f18v.P.8','f19v.P.2','f24v.P.14','f43v.P.15','f57v.R3.1','f57v.X.4']:
 body+='<details><summary>'+e(l)+'</summary>'+''.join('<p>'+e(x['reading']+': '+x['raw'])+'</p>' for x in a[l])+'</details>'
body+='<h2>The medieval bridge is real; the plant name needs care</h2><p>Gower’s late-fourteenth-century Confessio Amantis VII.1320–1327 explicitly associates Clota/Pliades with crystal and fennel. This is a pre-Voynich witness for the correspondence, without relying on a modern table. In VII.1310–1318 Aldeboran instead has Carbunculum and Anabulla. A historical medical text connects Anabulla/titimaillus with spurge. The later English Agrippa has “Milky Thistle”; equating that wording to the modern species Silybum marianum would require another taxonomic step. Retain both traditions rather than silently imposing one botanical identity.</p><p>No fennel illustration has been independently selected in this audit, so no fennel-page association is claimed. The cluster as Pleiades remains a conditional identification; it does not transfer to the connector or Aries figure label.</p>'
for x in sources:body+='<p><a href="'+x['url']+'">'+e(x['title'])+'</a> · '+e(x['date'])+'<br>'+e(x['finding'])+'</p>'
body+='<h2>The degree-test handoff is superseded</h2><p>The later development-image audit reports mixed known clothing in five of14 eligible groups: f70v1 outer, f71r inner, f71v outer and inner, f72r2 outer. Enclosures remain uniform among known eligible cases. Thus v87 was correct about its stored annotations, but the drawings do not support “clothing never varies within a ring.” The newer audit was by the same agent, not an independent blinded annotator; no new alignment result follows. Labels and colour are not the only logically possible information channels.</p><p><a href="../zodiac-image-audit-v88/report.html">Corrected image observations and evidence</a></p>'
body+='<h2>Forward candidate register</h2><p>oalch- is now recorded for subsequent exploratory work, with unstripped/o/oa/oal views and disputed allchdm kept separate. Old frozen tests remain unchanged. Modern tables are admissible as dated hypotheses, with author, source and earliest verified attestation recorded; a modern match alone cannot date a rule’s origin. Failure of a frozen retrieval only means no link was found under that retrieval, while a pass still requires spelling/hand/layout and plant-identification controls.</p><pre>'+e(json.dumps(register,indent=2))+'</pre>'
body+='<h2>All18 reading codes · coverage stays visible</h2><table><tr><th>Code</th><th>Tokens</th><th>Astro tokens</th><th>Contains alch</th><th>Starts alch</th><th>oalch tokens</th><th>Final g</th></tr>'
for x in s:body+='<tr>'+''.join('<td>'+e(v)+'</td>' for v in [x['reading'],x['tokens'],x['sections'].get('Astronomy/Astrology',0),x['alch_substring'],x['alch_initial'],len(x['oalch']),x['final_g']])+'</tr>'
body+='</table><p>These codes have very different coverage and editorial dependencies; they are not eighteen complete independent transcriptions. An absence may be lack of coverage. All matches use fully readable tokens only; damaged readings stay in the alternate records.</p>'
body+='<h2>Reproducible records</h2>'
for n in ['PROTOCOL.json','PRE-SEARCH-FREEZE.json','EXECUTION-NOTES.json','COUNTS.json','SUMMARY.json','EVENTS.json','ALTERNATES.json','CANDIDATE-REGISTER.json','FINDINGS.json','SOURCES.json','VERIFICATION.json']:
 body+='<p><a href="'+n+'">'+n+'</a></p>'
(R/'report.html').write_text('<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>oalch and historical correspondences · v90</title><style>body{font:17px system-ui;line-height:1.6;max-width:1050px;margin:40px auto;padding:0 20px;color:#173c38;background:#f6f2e8}h1,h2{line-height:1.2}h2{margin-top:2em}table{border-collapse:collapse;width:100%;font-size:14px}td,th{border:1px solid #b5c6bc;padding:7px;text-align:left}pre{white-space:pre-wrap;font-size:14px}details{padding:8px;border-bottom:1px solid #b5c6bc}a{color:#126151}</style>'+body+'</html>',encoding='utf-8')
